const raw = $input.first().json.candidates[0].content.parts[0].text;

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  let repaired = raw.trim();
  if (!repaired.endsWith(']')) {
    const lastCompleteObject = repaired.lastIndexOf('},');
    if (lastCompleteObject !== -1) {
      repaired = repaired.substring(0, lastCompleteObject + 1) + ']';
    } else {
      repaired = repaired + ']';
    }
  }
  parsed = JSON.parse(repaired);
}

return parsed.map(item => ({
  json: item
}));

const raw = $input.item.json.candidates[0].content.parts[0].text;
const analysis = JSON.parse(raw);

return {
  json: {
    ...$('Fit Score Gate').item.json,
    required_skills: analysis.required_skills,
    ats_keywords: analysis.ats_keywords,
    seniority: analysis.seniority,
    years_experience: analysis.years_experience,
    nice_to_have: analysis.nice_to_have,
    culture_signals: analysis.culture_signals
  }
};

const existingUrls = new Set(
  $('Get Existing URLs').all().map(item => item.json.URL || item.json.url)
);

const newJobs = $('Trim Job Fields').all();

const uniqueJobs = newJobs.filter(job => !existingUrls.has(job.json.url));

return uniqueJobs;
